/* Course content for "Write Your Way In: Academic Writing for Multilingual Learners".
   Extracted from Wemimo Aluko's Articulate Rise course. Edit the text here to update the course. */
window.COURSE = {"title":"Write Your Way In: Academic Writing for Multilingual Learners","description":"\u003cp\u003eLearn to plan, draft, revise, and edit academic writing in English, using all the languages you know. Discover how academic genres work, use sources with confidence, and turn feedback into real improvement. You will finish with a polished essay and a portfolio you can share with universities, employers, or journal editors.\u003c/p\u003e","lessons":[{"title":"Welcome","kind":"lesson","intro":"","passingScore":null,"blocks":[{"t":"text","level":2,"heading":"Welcome","html":"\u003cp\u003eYou are about to begin a course that helps you write with confidence in academic English. You will use all the languages you know, learn how academic writing works, and build a portfolio you can share.\u003c/p\u003e"},{"t":"text","level":2,"heading":"By the end of this course, you’ll be able to","html":""},{"t":"list","style":"number","items":["\u003cp\u003eExplain writing as a recursive process and use a personal drafting routine.\u003c/p\u003e","\u003cp\u003eIdentify the purpose, audience, and structure of common academic genres.\u003c/p\u003e","\u003cp\u003eWrite clear, well-supported paragraphs, summaries, and essays.\u003c/p\u003e","\u003cp\u003eParaphrase and cite sources in APA 7 without plagiarizing.\u003c/p\u003e","\u003cp\u003eUse direct, indirect, and metalinguistic feedback to revise accurately.\u003c/p\u003e","\u003cp\u003eUse AI tools responsibly as a writing partner, not a ghostwriter.\u003c/p\u003e"]},{"t":"text","level":2,"heading":"How this course works","html":"\u003cp\u003eThe course has four modules. Each module has short lessons, a self-check quiz, and a writing task. Plan for about 3 to 4 hours per week. You are welcome to plan and brainstorm in any language you know. Your final writing is in English.\u003c/p\u003e"},{"t":"divider"}]},{"title":"Module 1: The Workshop","kind":"section","intro":"","passingScore":null,"blocks":[]},{"title":"Diagnostic Writing","kind":"lesson","intro":"","passingScore":null,"blocks":[{"t":"text","level":2,"heading":"Purpose","html":"\u003cp\u003eThis task shows where you are starting. It is not graded for accuracy. You will compare it with your final essay at the end of the course.\u003c/p\u003e"},{"t":"text","level":2,"heading":"Your task","html":"\u003cp\u003e\u003cem\u003eWrite one paragraph (200 to 250 words) in English on this prompt:\u003c/em\u003e\u003cem\u003e“Describe a challenge that learners face when writing in academic English, and explain why it is important to address this challenge.”\u003c/em\u003e\u003c/p\u003e"},{"t":"text","level":3,"heading":"\u003cstrong\u003eSteps\u003c/strong\u003e","html":""},{"t":"process","items":[{"kind":"intro","title":"Plan","html":"\u003cp\u003eUse your Translanguaging Brainstorm and outline from Worksheet 1.\u003c/p\u003e"},{"kind":"step","title":"Draft","html":"\u003cp\u003eWrite your paragraph in one sitting.\u003c/p\u003e"},{"kind":"step","title":"Rest","html":"\u003cp\u003eWait at least a few hours, then reread it aloud.\u003c/p\u003e"},{"kind":"step","title":"Revise","html":"\u003cp\u003eMake small changes. Do not use AI tools or a tutor for this task, because it needs to show your current level.\u003c/p\u003e"},{"kind":"step","title":"Check","html":"\u003cp\u003eComplete the self-assessment checklist below.\u003c/p\u003e"},{"kind":"summary","title":"Submit","html":"\u003cp\u003eSend your paragraph and checklist using the link below.\u003c/p\u003e"}]},{"t":"text","level":3,"heading":"\u003cstrong\u003eChecklists\u003c/strong\u003e","html":""},{"t":"list","style":"check","items":["\u003cp\u003eMy paragraph has one clear main idea.\u003c/p\u003e","\u003cp\u003eMy ideas are in a logical order.\u003c/p\u003e","\u003cp\u003eI gave at least one example or reason.\u003c/p\u003e","\u003cp\u003eMy sentences are mostly clear.\u003c/p\u003e","\u003cp\u003eI used a few linking words (for example, however, because).\u003c/p\u003e","\u003cp\u003eI reread and made at least one change.\u003c/p\u003e"]},{"t":"text","level":2,"heading":"How to submit","html":"\u003cp\u003eClick the button below to open the submission form. Paste your paragraph, your outline, your checklist answers.\u003c/p\u003e"},{"t":"button","label":"Submit here","desc":"Submit your diagnostic writing","href":"mailto:wemimoaluko@gmail.com"},{"t":"divider"}]},{"title":"1.1 Why academic writing feels hard","kind":"lesson","intro":"","passingScore":null,"blocks":[{"t":"text","level":2,"heading":"Learning goal","html":"\u003cp\u003eName what makes academic writing difficult and see it as a learnable skill.\u003c/p\u003e"},{"t":"text","level":2,"heading":"\u003cstrong\u003eWhy it feels so hard\u003c/strong\u003e","html":"\u003cp\u003eMany learners say, “My English is not good enough for academic writing.” Usually, that is not the real problem. Academic writing is difficult for almost everyone, including people who speak English as a first language, because it follows rules that are rarely taught directly.\u003c/p\u003e"},{"t":"flashcards","items":[{"front":"\u003cp\u003e\u003cstrong\u003eAcademic writing\u003c/strong\u003e\u003c/p\u003e","back":"\u003cp\u003eWriting for university or research readers, with clear structure, evidence, and a formal style.\u003c/p\u003e"},{"front":"\u003cp\u003e\u003cstrong\u003eHidden rules\u003c/strong\u003e\u003c/p\u003e","back":"\u003cp\u003eExpectations about structure and style that teachers assume you know but rarely explain.\u003c/p\u003e"},{"front":"\u003cp\u003e\u003cstrong\u003eProduct-focused teaching\u003c/strong\u003e\u003c/p\u003e","back":"\u003cp\u003eTeaching that looks only at the final text, not the steps used to write it.\u003c/p\u003e"},{"front":"\u003cp\u003e\u003cstrong\u003eWriting process\u003c/strong\u003e\u003c/p\u003e","back":"\u003cp\u003eThe steps writers use to plan, draft, revise, and edit.\u003c/p\u003e"}]},{"t":"accordion","items":[{"title":"Hidden rules","html":"\u003cp\u003eTeachers often expect you to know how to organize an essay, support a claim, or sound “academic,” but nobody explained these things clearly.\u003c/p\u003e"},{"title":"Two jobs at once","html":"\u003cp\u003eYou must develop ideas and express them in a second language. That takes more mental effort, and it is normal to feel tired.\u003c/p\u003e"},{"title":"Product-only teaching","html":"\u003cp\u003eMany learners were taught to memorize and produce one finished text for an exam. They were never taught how to plan, revise, and improve.\u003c/p\u003e"}]},{"t":"statement","html":"\u003cp\u003eAll three challenges can be learned.\u003c/p\u003e"},{"t":"text","level":2,"heading":"\u003cstrong\u003eA short story\u003c/strong\u003e","html":"\u003cp\u003eImagine two students, Amara and Luis. Both write a first draft the night before the deadline. Amara hands it in. Luis puts it away, reads it again the next morning, moves two paragraphs, and adds an example. Their English is similar. Luis’s essay is better, not because he knows more grammar, but because he used a process.\u003c/p\u003e"},{"q":"Why was Luis’s essay better than Amara’s?","feedback":"\u003cp\u003eTheir English was similar. The difference was the process.\u003c/p\u003e","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"He used a process: he set it aside, reread it, moved paragraphs, and added an example.","correct":true},{"html":"He wrote a longer essay.","correct":false},{"html":"He used harder words.","correct":false}],"check":true},{"q":"True or false: Finding academic writing hard means you are a weak writer.","feedback":"\u003cp\u003eAcademic writing is hard for almost everyone. It is a skill you can learn.\u003c/p\u003e","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"True","correct":false},{"html":"False","correct":true}],"check":true},{"t":"note","html":"\u003cp\u003e\u003cstrong\u003eTry it (3 minutes)\u003c/strong\u003e \u003cem\u003eWrite for three minutes, in any language you like, about why you want to improve your academic writing. Do not stop to correct anything. Keep this note. You will use it in Lesson 1.4.\u003c/em\u003e\u003c/p\u003e"},{"t":"text","level":2,"heading":"Key ideas,","html":"\u003cp\u003eRemember these three points from this lesson.\u003c/p\u003e"},{"t":"list","style":"number","items":["\u003cp\u003eAcademic writing is a skill, not a talent.\u003c/p\u003e","\u003cp\u003eFeeling that writing is hard does not mean you are a weak writer.\u003c/p\u003e","\u003cp\u003eA process will help you more than extra grammar rules.\u003c/p\u003e"]},{"t":"divider"}]},{"title":"1.2 The writing process cycle","kind":"lesson","intro":"","passingScore":null,"blocks":[{"t":"text","level":2,"heading":"Learning goal","html":"\u003cp\u003eDescribe the stages of the writing process and explain why writers move back and forth between them.\u003c/p\u003e"},{"t":"process","items":[{"kind":"intro","title":"The Four Stages","html":"\u003cp\u003eWriting moves through four stages. Select each step to explore it.\u003c/p\u003e"},{"kind":"step","title":"Plan","html":"\u003cp\u003eDecide what you want to say, who you are writing for, and why. Gather ideas, brainstorm, and make a rough outline.\u003c/p\u003e"},{"kind":"step","title":"Draft","html":"\u003cp\u003eGet your ideas onto the page. Do not worry about perfect sentences. A first draft is meant to be imperfect.\u003c/p\u003e"},{"kind":"step","title":"Revise","html":"\u003cp\u003eLook at the big picture. Do your ideas make sense? Is the order clear? Is anything missing or unnecessary? Move, add, and delete.\u003c/p\u003e"},{"kind":"step","title":"Edit","html":"\u003cp\u003eLook at the small picture. Check grammar, word choice, spelling, punctuation, and formatting.\u003c/p\u003e"},{"kind":"summary","title":"Summary","html":"\u003cp\u003eWriting moves through four stages: plan, draft, revise, and edit. These stages are not a straight line. Writers often go back to an earlier stage as their ideas change, and that is a normal part of writing. Revise first, then edit.\u003c/p\u003e"}]},{"t":"text","level":2,"heading":"Writing is recursive","html":"\u003cp\u003eThe stages are not a straight line. Researchers who study how people write, including Flower and Hayes in a well-known 1981 model, showed that writers keep moving between planning, drafting, and reviewing. You may plan, draft a paragraph, realize your plan has a gap, and plan again. That is not failure. That is how writing works.\u003c/p\u003e"},{"t":"tabs","items":[{"title":"Revising","html":"\u003cp\u003e\u003cem\u003eFocus: ideas, structure, support. Question: Does this make sense and persuade? When: early, after the first draft.\u003c/em\u003e\u003c/p\u003e"},{"title":"Editing","html":"\u003cp\u003eFocus: grammar, spelling, style. Question: Is this correct and clear? When: late, near the end.\u003c/p\u003e"}]},{"t":"sorting","piles":["Revising","Editing"],"items":[{"html":"Adding an example to a weak paragraph","pile":0},{"html":"Changing “there is” to “there are”","pile":1},{"html":"Moving a paragraph to a better place","pile":0},{"html":"Deleting a sentence that is off topic","pile":0},{"html":"Fixing a spelling mistake","pile":1},{"html":"Adding a missing comma","pile":1}]},{"t":"note","html":"\u003cp\u003e\u003cstrong\u003eCommon mistake\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eFixing grammar too early. If you polish a paragraph and later delete it, that time was wasted. Revise first, edit last.\u003c/p\u003e"},{"t":"note","html":"\u003cp\u003e\u003cstrong\u003eTry it (5 minutes)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eThink of the last thing you wrote. Which stages did you do? Which did you skip? Write one sentence about what you will try next time.\u003c/p\u003e"},{"t":"text","level":2,"heading":"Key ideas","html":""},{"t":"list","style":"number","items":["\u003cp\u003eWriting has four stages: plan, draft, revise, edit.\u003c/p\u003e","\u003cp\u003eGood writers move back and forth between the stages.\u003c/p\u003e","\u003cp\u003eRevise before you edit.\u003c/p\u003e"]},{"t":"divider"}]},{"title":"1.3 Plan in any language","kind":"lesson","intro":"","passingScore":null,"blocks":[{"t":"text","level":2,"heading":"\u003cstrong\u003eLearning goal\u003c/strong\u003e","html":"\u003cp\u003eUse all of your languages to generate and organize ideas before you write in English.\u003c/p\u003e"},{"t":"text","level":2,"heading":"Your languages are an advantage","html":"\u003cp\u003eIf you speak more than one language, you can think about a topic in different ways, using different words, examples, and proverbs. Many people believe they must think only in English when they write in English. Research on multilingual learners suggests that using all your languages can help you understand and plan better. This is sometimes called translanguaging.\u003c/p\u003e"},{"t":"flashcards","items":[{"front":"\u003cp\u003e\u003cstrong\u003eTranslanguaging\u003c/strong\u003e\u003c/p\u003e","back":"\u003cp\u003eUsing all of your languages to think, plan, and make meaning.\u003c/p\u003e"},{"front":"\u003cp\u003e\u003cstrong\u003eBrainstorm\u003c/strong\u003e\u003c/p\u003e","back":"\u003cp\u003eWriting down every idea you have about a topic without judging it.\u003c/p\u003e"},{"front":"\u003cp\u003e\u003cstrong\u003eKey term\u003c/strong\u003e\u003c/p\u003e","back":"\u003cul\u003e\u003cli\u003e\u003cp\u003eThe main English word or phrase for an important idea in your notes.\u003c/p\u003e\u003c/li\u003e\u003c/ul\u003e"},{"front":"\u003cp\u003e\u003cstrong\u003eDraft\u003c/strong\u003e\u003c/p\u003e","back":"\u003cp\u003eA first version of your writing, written in English from your notes.\u003c/p\u003e"}]},{"t":"accordion","items":[{"title":"I must think only in English","html":"\u003cp\u003e Fact: Thinking in your home languages first can help you find better ideas. You only need English for the final writing.\u003c/p\u003e"},{"title":"Using my home language means my English is weak","html":"\u003cp\u003eFact: Strong multilingual writers use all their languages as thinking tools.\u003c/p\u003e"},{"title":"A translation tool can do my planning for me","html":"\u003cp\u003eFact: Tools can help you check a word, but the ideas and choices must be yours.\u003c/p\u003e"}]},{"t":"process","items":[{"kind":"intro","title":"The Translanguaging Brainstorm","html":""},{"kind":"step","title":"Brainstorm freely","html":"\u003cp\u003eWrite everything you know about your topic in any language, or mix languages. Use words, short phrases, or sentences. \u003cem\u003eTip: set a 3-minute timer.\u003c/em\u003e\u003c/p\u003e"},{"kind":"step","title":"Sort your ideas","html":"\u003cp\u003eGroup related ideas together. Cross out repeated ones. \u003cem\u003eTip: give each group a short label.\u003c/em\u003e\u003c/p\u003e"},{"kind":"step","title":"Choose key terms","html":"\u003cp\u003eFind the English words for your main ideas. \u003cem\u003eTip: check the meaning in a sentence, not just a word list.\u003c/em\u003e\u003c/p\u003e"},{"kind":"summary","title":"Draft in English","html":"\u003cp\u003eUse your notes as support. You do not need to translate word for word. \u003cem\u003eTip: start with one clear sentence.\u003c/em\u003e\u003c/p\u003e"}]},{"t":"text","level":2,"heading":"See it in action","html":"\u003cp\u003e\u003cem\u003eWhy is it hard for students to speak in class?\u003c/em\u003e\u003c/p\u003e"},{"t":"tabs","items":[{"title":"Notes","html":"\u003cp\u003efear of mistakes, “people will laugh,” shy, teacher is strict, not enough practice, culture of respect\u003c/p\u003e"},{"title":"Sorted","html":"\u003cp\u003eEmotional reasons (fear, shyness) | Social reasons (laughing, respect for teachers) | Practice reasons (not enough speaking time)\u003c/p\u003e"},{"title":"Key terms","html":"\u003cp\u003ebarriers, anxiety, classroom culture, practice opportunities\u003c/p\u003e"},{"title":"First sentence","html":"\u003cp\u003eStudents may avoid speaking in class because of emotional, social, and practical barriers.\u003c/p\u003e"}]},{"t":"text","level":2,"heading":"","html":"\u003cp\u003eDrag each idea into the right group\u003c/p\u003e"},{"t":"sorting","piles":["Emotional","Social","Practice"],"items":[{"html":"Fear of making mistakes","pile":0},{"html":"Classmates might laugh","pile":1},{"html":"Feeling shy","pile":0},{"html":"Respect for the teacher","pile":1},{"html":"Not enough speaking time","pile":2},{"html":"Few chances to practice aloud","pile":2}]},{"t":"note","html":"\u003cp\u003e\u003cstrong\u003eImportant\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eHome-language planning is a thinking tool. Your final text for this course should be in English, and you should not translate full paragraphs with a tool and submit them as your own writing.\u003c/p\u003e"},{"t":"text","level":2,"heading":"Try it (10 minutes)","html":"\u003cp\u003eChoose the topic “A challenge learners face in academic writing.” Do the four steps: brainstorm, sort, choose key terms, and write your first English sentence. Use Worksheet 1.\u003c/p\u003e"},{"t":"text","level":2,"heading":"My planning checklist","html":""},{"t":"list","style":"check","items":["\u003cp\u003eI wrote ideas in any language, without stopping.\u003c/p\u003e","\u003cp\u003eI sorted my ideas into groups.\u003c/p\u003e","\u003cp\u003eI chose English key terms for my main ideas.\u003c/p\u003e","\u003cp\u003eI wrote one clear first sentence in English.\u003c/p\u003e"]},{"t":"text","level":2,"heading":"Key ideas","html":""},{"t":"list","style":"number","items":["\u003cp\u003eYour other languages are resources, not problems.\u003c/p\u003e","\u003cp\u003ePlan first, translate ideas second, and polish last.\u003c/p\u003e","\u003cp\u003eCheck translated words in context.\u003c/p\u003e"]},{"t":"divider"}]},{"title":"1.4 Beat the blank page","kind":"lesson","intro":"","passingScore":null,"blocks":[{"t":"text","level":2,"heading":"\u003cstrong\u003eLearning goal\u003c/strong\u003e","html":"\u003cp\u003eUse freewriting and a simple outline to start writing with less stress.\u003c/p\u003e"},{"t":"text","level":2,"heading":"Why the blank page feels scary","html":"\u003cp\u003e\u003cem\u003eMany writers feel stuck at the start. They wait for the perfect idea or the perfect first sentence. But ideas often arrive while you are writing, not before. Good writers start before they feel ready, then shape their ideas step by step.\u003c/em\u003e\u003c/p\u003e"},{"t":"text","level":3,"heading":"\u003cstrong\u003eKey terms\u003c/strong\u003e","html":""},{"t":"flashcards","items":[{"front":"\u003cp\u003e\u003cstrong\u003eFreewriting\u003c/strong\u003e\u003c/p\u003e","back":"\u003cp\u003eWriting without stopping and without correcting, for a set amount of time.\u003c/p\u003e"},{"front":"\u003cp\u003e\u003cstrong\u003eOutline\u003c/strong\u003e\u003c/p\u003e","back":"\u003cp\u003eA quick map of your main idea, your points, and your examples.\u003c/p\u003e"},{"front":"\u003cp\u003e\u003cstrong\u003eMain idea\u003c/strong\u003e\u003c/p\u003e","back":"\u003cp\u003eThe one sentence that tells your reader what your writing is about.\u003c/p\u003e"},{"front":"\u003cp\u003e\u003cstrong\u003eExample\u003c/strong\u003e\u003c/p\u003e","back":"\u003cul\u003e\u003cli\u003e\u003cp\u003eA fact, reason, or story that supports one of your points.\u003c/p\u003e\u003c/li\u003e\u003c/ul\u003e"}]},{"t":"tabs","items":[{"title":"Freewriting","html":"\u003cp\u003e\u003cem\u003eSet a timer for 5 to 10 minutes. Keep your hand or fingers moving. Do not delete anything. If you get stuck, write “I am stuck” until a new idea comes. The goal is to get ideas out, not to write well.\u003c/em\u003e\u003c/p\u003e"},{"title":"Outlining","html":"\u003cp\u003e\u003cem\u003eAn outline is a quick map of your writing. It does not need to be neat. It has a main idea, two or three points, an example for each point, and a closing thought.\u003c/em\u003e\u003c/p\u003e"},{"title":"Other ways to start","html":"\u003cp\u003e\u003cem\u003eQuestion list: write 5 questions your reader might ask about your topic. Talk it out: record yourself explaining the topic on your phone, then listen and write down the key points. Start in the middle: begin with the easiest paragraph, not the introduction.\u003c/em\u003e\u003c/p\u003e"}]},{"t":"text","level":3,"heading":"Freewriting: do or don’t?","html":""},{"t":"sorting","piles":["Do","Don’t"],"items":[{"html":"Set a timer","pile":0},{"html":"Stop to fix grammar","pile":1},{"html":"Keep your hand moving","pile":0},{"html":"Write “I am stuck” when you are stuck","pile":0},{"html":"Delete sentences as you go","pile":1},{"html":"Wait for the perfect idea","pile":1}]},{"t":"process","items":[{"kind":"intro","title":"Build an outline in 4 steps","html":""},{"kind":"step","title":"Write your main idea","html":"\u003cp\u003eOne sentence that says what your paragraph is about.\u003c/p\u003e"},{"kind":"step","title":"Choose your points","html":"\u003cp\u003ePick two or three points that support the main idea.\u003c/p\u003e"},{"kind":"step","title":"Add an example","html":"\u003cp\u003eGive each point one example, reason, or fact.\u003c/p\u003e"},{"kind":"summary","title":"Write a closing thought","html":"\u003cp\u003eOne sentence that connects your points back to the main idea.\u003c/p\u003e"}]},{"t":"text","level":2,"heading":"Why academic writing is hard for new students","html":""},{"t":"accordion","items":[{"title":"Main idea","html":"\u003cp\u003e\u003cem\u003eAcademic writing is hard for new students because the rules are hidden, the language is new, and they rarely practice a process.\u003c/em\u003e\u003c/p\u003e"},{"title":"Points and examples","html":"\u003cp\u003e\u003cem\u003ePoint 1: Hidden rules. Example: Teachers expect a thesis statement but never explain it. Point 2: New language. Example: Students know the idea but not the English word. Point 3: No process. Example: Students write one draft the night before.\u003c/em\u003e\u003c/p\u003e"},{"title":"Closing thought","html":"\u003cp\u003eThese barriers can all be reduced with explicit teaching and practice.\u003c/p\u003e"}]},{"q":"What is the main goal of freewriting?","feedback":"\u003cp\u003eFreewriting helps ideas appear. You can organize and correct them later.\u003c/p\u003e","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"To write a perfect first paragraph","correct":false},{"html":"To get ideas out without worrying about mistakes","correct":true},{"html":"To practice grammar","correct":false}],"check":true},{"t":"text","level":2,"heading":"Quick check 2","html":""},{"q":"Match each strategy to what it does.","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"match","pairs":[{"a":"Freewriting","b":"Write without stopping for a set time"},{"a":"Outline","b":"Map your main idea, points, and examples"},{"a":"Question list","b":"Write 5 questions your reader might ask"},{"a":"Talk it out","b":"Record yourself explaining the topic, then note the key points"}],"check":true},{"t":"note","html":"\u003cp\u003e\u003cstrong\u003eTry it (15 minutes)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cem\u003eLook at the three-minute note you wrote in Lesson 1.1. (If you did not write one, freewrite for three minutes now about why you want to improve your academic writing.) Highlight your three most useful ideas. Turn them into an outline for one paragraph, using the four steps above.\u003c/em\u003e\u003c/p\u003e"},{"t":"divider"}]},{"title":"Module 1 Self-Check","kind":"quiz","intro":"\u003cp\u003eModule 1 quiz\u003c/p\u003e","passingScore":80,"blocks":[{"q":"Which stage focuses on grammar, spelling, and punctuation?","feedback":"\u003cp\u003eEditing focuses on small details. Revising looks at ideas and structure.\u003c/p\u003e","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Planning","correct":false},{"html":"Drafting","correct":false},{"html":"Revising","correct":false},{"html":"Editing","correct":true}]},{"q":"Why is writing described as \"recursive\"?","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Writers must follow the four stages in a fixed order.","correct":false},{"html":"Writers often move back and forth between stages.","correct":true},{"html":"Writers only revise at the end.","correct":false},{"html":"Writers should write the same text many times.","correct":false}]},{"q":"What is the best advice for a student who fixes every grammar mistake in a first draft and then deletes two paragraphs?","feedback":"Revising first and editing later is a key strategy to improve writing efficiency and effectiveness.","feedbackCorrect":"Correct! Revising ideas and structure first allows for a more efficient editing process.","feedbackIncorrect":"Incorrect. Consider focusing on revising the content and structure before addressing grammar.","t":"choice","multi":false,"answers":[{"html":"Never delete paragraphs.","correct":false},{"html":"Write only short paragraphs.","correct":false},{"html":"Avoid grammar completely.","correct":false},{"html":"Fix grammar later, after revising ideas and structure.","correct":true}]},{"q":"What is the main purpose of a first draft?","feedback":"A first draft is a tool to help you begin organizing your ideas and thoughts for further refinement.","feedbackCorrect":"Great job! Capturing ideas is the essence of drafting.","feedbackIncorrect":"Remember, the first draft is about organizing your thoughts, not perfection or complexity.","t":"choice","multi":false,"answers":[{"html":"To use difficult vocabulary","correct":false},{"html":"To get ideas on the page","correct":true},{"html":"To be perfect","correct":false},{"html":"To impress the reader","correct":false}]},{"q":"Which of the following is an example of using translanguaging in planning?","feedback":"Using your languages to think is helpful. Submitting machine-translated text as your own work is not.","feedbackCorrect":"Great job! Using multiple languages to plan and think enriches the writing process.","feedbackIncorrect":"Not quite. Remember, translanguaging involves actively using your languages to think and plan.","t":"choice","multi":false,"answers":[{"html":"Translating a whole essay with a tool and submitting it","correct":false},{"html":"Writing notes in more than one language, then drafting in English","correct":true},{"html":"Using only a dictionary","correct":false},{"html":"Avoiding your home language completely","correct":false}]},{"q":"What is the primary guideline to follow during freewriting?","feedback":"Freewriting is a technique to generate ideas by writing continuously without concern for mistakes or structure.","feedbackCorrect":"Correct! Freewriting is about maintaining a continuous flow of ideas without interruptions.","feedbackIncorrect":"Incorrect. Remember, freewriting emphasizes uninterrupted writing to foster creativity and idea generation.","t":"choice","multi":false,"answers":[{"html":"Use only perfect sentences","correct":false},{"html":"Keep writing without stopping for a set time","correct":true},{"html":"Write only in English","correct":false},{"html":"Stop often to fix mistakes","correct":false}]},{"q":"Which of the following actions represents revising in the writing process?","feedback":"Revising is about enhancing the content and structure of your writing, while editing focuses on correcting grammar and mechanics.","feedbackCorrect":"Correct! Revising involves improving the content, structure, and support of your writing.","feedbackIncorrect":"Not quite. Remember, revising focuses on improving ideas and structure, while editing addresses grammar and mechanics.","t":"choice","multi":false,"answers":[{"html":"Fixing a spelling mistake","correct":false},{"html":"Changing \u0027there is\u0027 to \u0027there are\u0027","correct":false},{"html":"Adding an example to a weak paragraph","correct":true},{"html":"Adding a missing comma","correct":false}]},{"q":"True or false: Needing several drafts shows that you are a weak writer.","feedback":"Drafting and revising are key steps in producing high-quality writing.","feedbackCorrect":"Correct! Revising and drafting are essential parts of the writing process.","feedbackIncorrect":"Incorrect. Writing multiple drafts is a strength, as it shows dedication to improving your work.","t":"choice","multi":false,"answers":[{"html":"False","correct":true},{"html":"True","correct":false}]}]},{"title":"Module 2: The Blueprint Room","kind":"section","intro":"","passingScore":null,"blocks":[]},{"title":"2.1 Anatomy of a paragraph","kind":"lesson","intro":"","passingScore":null,"blocks":[{"t":"text","level":2,"heading":"Learning goal","html":"\u003cp\u003eWrite a paragraph with a topic sentence, support, an example, and a closing link.\u003c/p\u003e"},{"t":"text","level":2,"heading":"One paragraph, one idea","html":"\u003cp\u003e\u003cem\u003eA paragraph develops one main idea. Readers expect a pattern: they see the idea first, then the support, then a way to move on. When your paragraph follows this pattern, your reader can follow your thinking easily.\u003c/em\u003e\u003c/p\u003e"},{"t":"process","items":[{"kind":"intro","title":"The four parts","html":""},{"kind":"step","title":"Topic sentence","html":"\u003cp\u003e\u003cem\u003eThis sentence tells your reader what the whole paragraph is about. It states one clear, specific idea, usually at the beginning, so your reader knows what to expect. Everything else in the paragraph should connect back to it. Tip: if you cannot say your main idea in one sentence, your paragraph probably holds more than one idea.\u003c/em\u003e\u003c/p\u003e"},{"kind":"step","title":"Support Title","html":"\u003cp\u003eHere you explain or prove your main idea. You can give reasons, explain how or why something happens, or add information from a reliable source. Support answers the question your reader is silently asking: “Why should I believe this?” Two or three sentences of support are usually enough for a short paragraph.\u003c/p\u003e"},{"kind":"step","title":"Example","html":"\u003cp\u003e\u003cem\u003eAn example makes your idea real. It can be a specific case, a fact, a short story, or a situation your reader can picture. Introduce it with a signal such as “for example” or “for instance,” and make clear how it connects to your main idea.\u003c/em\u003e\u003c/p\u003e"},{"kind":"summary","title":"Closing link","html":"\u003cp\u003eThe last sentence finishes your idea and shows why it matters. It may sum up your point in new words, or prepare your reader for the next paragraph. Do not add a brand-new idea here, and do not simply copy your first sentence word for word.\u003c/p\u003e"}]},{"t":"text","level":3,"heading":"Which part is it?","html":"\u003cp\u003eInstruction: \u003cem\u003eRead the sample paragraph parts below about sleep and studying. Drag each sentence into the group that matches its job in the paragraph. Think about what each sentence does, not only what it says\u003c/em\u003e\u003c/p\u003e"},{"t":"sorting","piles":["Topic sentence","Support","Example","Closing link"],"items":[{"html":"Regular sleep helps students learn more effectively.","pile":0},{"html":"During sleep, the brain organizes what it learned during the day.","pile":1},{"html":"For instance, a student who sleeps before an exam may remember more than one who","pile":2},{"html":"Therefore, protecting sleep time is a smart study strategy.","pile":3}]},{"q":"Which is the best topic sentence for a paragraph about online learning?","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Online learning is a thing many people do.","correct":false},{"html":"Online learning gives working adults flexible access to higher education.","correct":true},{"html":"I like online learning because it is nice.","correct":false},{"html":"There are many kinds of learning.","correct":false}],"check":true},{"t":"note","html":"\u003cp\u003e\u003cstrong\u003eTry it\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eWrite one topic sentence for this idea: “Why students should use a writing process.” Make it specific. Then check it: Does it state one idea? Could you support it with two or three reasons? If not, rewrite it once.\u003c/p\u003e"},{"t":"text","level":3,"heading":"Key ideas","html":""},{"t":"list","style":"number","items":["\u003cp\u003eA paragraph develops one main idea, and a new idea begins a new paragraph.\u003c/p\u003e","\u003cp\u003e\u003cem\u003eA strong paragraph has four parts: a topic sentence, support, an example, and a closing link.\u003c/em\u003e\u003c/p\u003e","\u003cp\u003e\u003cem\u003eA good topic sentence is specific enough that you can support it in a few sentences.\u003c/em\u003e\u003c/p\u003e"]},{"t":"divider"}]},{"title":"2.2 Clear and connected","kind":"lesson","intro":"","passingScore":null,"blocks":[{"t":"text","level":2,"heading":"Learning goal","html":"\u003cp\u003eBy the end of this lesson, you will be able to use the 4 Cs and linking words to make your paragraph clear, connected, and easy to read.\u003c/p\u003e"},{"t":"text","level":2,"heading":"Why connection matters","html":"\u003cp\u003eGood ideas can still confuse a reader if they are not connected. Readers need signals that tell them how one sentence relates to the next. In this lesson, you will learn four qualities of clear writing, called the 4 Cs, and a set of small words that connect ideas.\u003c/p\u003e"},{"t":"text","level":3,"heading":"The 4 Cs","html":""},{"t":"flashcards","items":[{"front":"\u003cp\u003eClarity\u003c/p\u003e","back":"\u003cp\u003e Each sentence carries one clear idea in words your reader understands. For example, “Many students struggle with essays” is clearer than “A lot of stuff is difficult in the matter of writing.”\u003c/p\u003e"},{"front":"\u003cp\u003eCoherence\u003c/p\u003e","back":"\u003cp\u003eYour ideas connect and follow a logical order, so the reader never feels lost. Linking words and repeated key terms help each sentence lead naturally to the next.\u003c/p\u003e"},{"front":"\u003cp\u003e\u003cstrong\u003eConciseness\u003c/strong\u003e\u003c/p\u003e","back":"\u003cp\u003eYou use only the words you need. Cut repeated ideas and filler phrases such as “it is a fact that” or “in my own opinion.” Shorter is often stronger.\u003c/p\u003e"},{"front":"\u003cp\u003eConsistency\u003c/p\u003e","back":"\u003cp\u003eYou keep the same tense, key terms, and style throughout. If you call people “learners” in your first sentence, do not switch to “pupils” and “scholars” later without a reason.\u003c/p\u003e"}]},{"t":"tabs","items":[{"title":"Add","html":"\u003cp\u003e\u003cem\u003eUse these words to add another point of the same kind. Examples: also, in addition, moreover, furthermore. Sentence: “Students need time to plan. In addition, they need feedback to improve.”\u003c/em\u003e\u003c/p\u003e"},{"title":"Contrast","html":"\u003cp\u003e\u003cem\u003eUse these words to show a difference or a surprise. Examples: however, but, although, on the other hand. Sentence: “Many students find essays hard. However, a clear process makes them easier.”\u003c/em\u003e\u003c/p\u003e"},{"title":"Cause and result","html":"\u003cp\u003e\u003cem\u003eUse these words to explain why something happens or what follows. Examples: because, since, therefore, as a result. Sentence: “Luis revised his draft. As a result, his essay was clearer.”\u003c/em\u003e\u003c/p\u003e"},{"title":"Example","html":"\u003cp\u003e\u003cem\u003eUse these words to introduce a specific case. Examples: for example, for instance, such as. Sentence: “Linking words, such as however and therefore, guide the reader.”\u003c/em\u003e\u003c/p\u003e"}]},{"q":"Instruction: \u003cem\u003eMatch each linking word to the job it does.\u003c/em\u003e","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"match","pairs":[{"a":"However","b":"Shows contrast"},{"a":"Therefore","b":"Shows a result"},{"a":"For example","b":"Introduces an example"},{"a":"In addition","b":"Adds another point"}],"check":true},{"q":"Many students find academic writing difficult. ______, regular practice can make it easier.","feedback":"\u003cp\u003e\u003cem\u003eYes. “However” shows a contrast between the difficulty in the first sentence and the hopeful idea in the second.\u003c/em\u003eIncorrect feedback: \u003cem\u003eThink about how the two sentences relate. The first states a problem, and the second offers a different, more positive idea. Which linking word shows that contrast?\u003c/em\u003e\u003c/p\u003e","feedbackCorrect":"","feedbackIncorrect":"","t":"fill","accepted":["However"],"check":true},{"t":"note","html":"\u003cp\u003e\u003cstrong\u003eTry it\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eOpen your diagnostic paragraph from Module 1. First, underline every linking word you used. Next, find two places where a reader might feel a jump between ideas. Add a linking word in each place, then read the paragraph aloud to check that it flows.\u003c/p\u003e"},{"t":"text","level":3,"heading":"Key ideas","html":""},{"t":"list","style":"number","items":["\u003cp\u003eThe 4 Cs are clarity, coherence, conciseness, and consistency.\u003c/p\u003e","\u003cp\u003eLinking words show readers how one idea relates to another.\u003c/p\u003e","\u003cp\u003eDo not use linking words just to fill space. Use one when it helps your reader follow your thinking.\u003c/p\u003e"]},{"t":"divider"}]},{"title":"2.3 Genre detectives","kind":"lesson","intro":"","passingScore":null,"blocks":[{"t":"text","level":2,"heading":"Learning goal","html":"\u003cp\u003eBy the end of this lesson, you will be able to identify the purpose, audience, and structure of a text and use these three clues to understand and write in a new genre.\u003c/p\u003e"},{"t":"text","level":2,"heading":"What is genre?","html":"\u003cp\u003eA genre is a type of text that people use to do a specific job. An email, a research abstract, a summary, and an essay are all genres. Each genre has a purpose (what the text is for), an audience (who will read it), and an expected structure (how it is organized). Learning these expectations is like learning the rules of a game. Once you know them, you can play with confidence instead of guessing.\u003c/p\u003e"},{"t":"text","level":3,"heading":"Three detective questions","html":""},{"t":"tabs","items":[{"title":"Purpose","html":"\u003cp\u003e\u003cem\u003eAsk: Why was this written? Some texts inform, some persuade, some request something, and some explain how to do something. Knowing the purpose tells you what the writer wanted to achieve.\u003c/em\u003e\u003c/p\u003e"},{"title":"Audience","html":"\u003cp\u003e\u003cem\u003eAsk: Who will read this? A scholarship committee, a professor, and a close friend all expect different language and levels of formality. Knowing the audience helps you choose words, tone, and detail.\u003c/em\u003e\u003c/p\u003e"},{"title":"Structure","html":"\u003cp\u003e\u003cem\u003eAsk: How is this organized? Look at what comes first, what comes in the middle, and how the text ends. Many genres follow a predictable order, which makes them easier to read and to write.\u003c/em\u003e\u003c/p\u003e"}]},{"t":"text","level":3,"heading":"Case files","html":""},{"t":"accordion","items":[{"title":"Scholarship email","html":"\u003cp\u003e\u003cem\u003ePurpose: to ask for support. Audience: a selection committee that reads many requests. Structure: a polite greeting, a clear request, two or three reasons, and a thank-you. Notice how the tone is respectful and the message is short.\u003c/em\u003e\u003c/p\u003e"},{"title":"Research abstract","html":"\u003cp\u003e\u003cem\u003ePurpose: to summarize a study so readers can decide whether to read the full article. Audience: researchers and students searching for studies. Structure: background, aim, method, results, and conclusion, usually in one short paragraph.\u003c/em\u003e\u003c/p\u003e"},{"title":"Academic paragraph","html":"\u003cp\u003ePurpose: to explain one idea clearly. Audience: an instructor and classmates. Structure: topic sentence, support, example, and closing link. This is the pattern you practiced in Lesson 2.1.\u003c/p\u003e"}]},{"t":"text","level":3,"heading":"Which genre?","html":"\u003cp\u003eInstruction: \u003cem\u003eEach feature below belongs to one genre. Drag it to the genre it fits best.\u003c/em\u003e\u003c/p\u003e"},{"t":"sorting","piles":["Email","Abstract","Paragraph"],"items":[{"html":"A greeting and sign-off; a clear request","pile":0},{"html":"Background, method, and results in a short text","pile":1},{"html":"A topic sentence followed by an example","pile":2}]},{"t":"text","level":3,"heading":"Quick check","html":""},{"q":"Who is the main audience of a research abstract?","feedback":"\u003cp\u003e Readers use abstracts to decide whether an article is relevant to their own work, so the abstract is written for people interested in the research topic.\u003c/p\u003e","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Researchers and readers searching for studies","correct":true},{"html":"Friends and family","correct":false},{"html":"Only the author","correct":false},{"html":"Social media followers","correct":false}],"check":true},{"t":"note","html":"\u003cp\u003eTry it (15 minutes)\u003c/p\u003e\u003cp\u003eChoose a short abstract from an open-access article in your field. Read it twice. Then answer the three detective questions in your own words: What is its purpose? Who is its audience? How is it organized? Write one or two sentences for each. You will use these notes in the assignment.\u003c/p\u003e"},{"t":"text","level":3,"heading":"Key ideas","html":""},{"t":"list","style":"number","items":["\u003cp\u003eA genre is a type of text that has a job to do.\u003c/p\u003e","\u003cp\u003ePurpose, audience, and structure are three clues that help you understand any genre.\u003c/p\u003e","\u003cp\u003eKnowing the genre helps you read faster and write with more confidence.\u003c/p\u003e"]},{"t":"divider"}]},{"title":"Module 2 Self-Check","kind":"quiz","intro":"Explore how well you understand the academic writing process—from planning, drafting, revising, and editing to building strong paragraphs with topic sentences, support, examples, and closing links. You’ll also check your knowledge of freewriting and outlines, using sources effectively, translanguaging as a brainstorming tool, genre clues like purpose and audience, and the 4 Cs of clear writing.","passingScore":80,"blocks":[{"q":"A writer reviews a paragraph and notices that the ideas are in a logical order, the same key terms are used throughout, and every sentence is easy to understand without extra filler. Which set of the 4 Cs does this paragraph demonstrate?","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Coherence, conciseness, and consistency","correct":false},{"html":"Clarity, conciseness, and consistency","correct":false},{"html":"Clarity, coherence, and consistency","correct":false},{"html":"Clarity, coherence, conciseness, and consistency","correct":true}]},{"q":"A student needs to read an unfamiliar text quickly and then write a similar text with confidence. Which approach best helps the student do both tasks?","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Identify the text’s purpose, audience, and structure before reading closely or drafting.","correct":true},{"html":"Choose words that sound formal before thinking about who will read the text.","correct":false},{"html":"Focus on memorizing every sentence before deciding what kind of text it is.","correct":false},{"html":"Look for one interesting example and use it as the model for the whole text.","correct":false}]},{"q":"A student is writing the diagnostic paragraph for this assignment. Which response best explains why it is important to address a challenge in academic English writing?","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"It helps learners include an outline and checklist because those are the most important parts of academic writing.","correct":false},{"html":"It helps learners improve communication so their ideas are clearer and more effective in academic work.","correct":true},{"html":"It helps learners finish the paragraph faster by skipping the planning and revision steps.","correct":false},{"html":"It helps learners add more linking words, even if the main idea of the paragraph is still unclear.","correct":false}]},{"q":"A student is writing an academic essay in English and first makes an outline, then writes a full first version, then improves ideas and organization, and finally corrects grammar and punctuation. Which sequence best matches the stages of the academic writing process?","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Planning, revising, drafting, editing","correct":false},{"html":"Planning, drafting, revising, editing","correct":true},{"html":"Drafting, planning, revising, editing","correct":false},{"html":"Planning, drafting, editing, revising","correct":false}]},{"q":"Revising comes before editing because writers should improve ideas and structure before correcting grammar and spelling.","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"False","correct":false},{"html":"True","correct":true}]},{"q":"Which practice best shows effective use of sources in academic writing?","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Introduce the source, cite it properly, and explain how it supports your point.","correct":true},{"html":"Copy the author’s idea exactly and include a citation after the sentence.","correct":false},{"html":"Add a source at the end of the paragraph to make the writing sound formal.","correct":false},{"html":"Mention several sources together without explaining how they relate to your claim.","correct":false}]},{"q":"Finding academic writing hard does not mean you are a weak writer.","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"False","correct":false},{"html":"True","correct":true}]},{"q":"You are planning one paragraph about why new students find academic writing difficult. Which outline best follows the four-step structure for building an outline?","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Main idea: Academic writing is hard for new students. Points: the rules are hidden; the language is new; students lack a process. Examples: teachers expect a thesis without explaining it; students know an idea but not the English word; students write one draft the night before. Closing thought: These problems can improve with clear teaching and practice.","correct":true},{"html":"Main idea: Academic writing is hard for new students. Points: write a perfect introduction; fix grammar first; wait for the best idea. Examples: polish each sentence; delete weak lines; start again if needed. Closing thought: Strong writing begins when every sentence is correct.","correct":false},{"html":"Main idea: Academic writing is hard for new students. Example: teachers expect a thesis without explaining it. Example: students know an idea but not the English word. Example: students write one draft the night before. Closing thought: These problems can improve with clear teaching and practice.","correct":false},{"html":"Main idea: Academic writing is hard for new students. Points: the rules are hidden; the language is new; students lack a process. Closing thought: These problems can improve with clear teaching and practice. Question: Why is writing so hard?","correct":false}]},{"q":"A student says, \"I need more grammar rules before I can write better academic essays.\" Based on this lesson, what is the best response?","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Write the whole essay in one sitting because fluent drafting is the most effective way to produce a stronger final version.","correct":false},{"html":"Use a writing process such as planning, drafting, rereading, and revising because that usually improves the essay more than extra grammar rules.","correct":true},{"html":"Study advanced grammar first because strong academic writing mainly depends on using more complex language correctly.","correct":false},{"html":"Memorize one polished essay model because academic writing improves most when you reproduce a finished text accurately.","correct":false}]},{"q":"Use the three genre clues to analyze how a text works. Match each detective question to the clue it helps you identify when reading a genre.","feedback":"","feedbackCorrect":"Correct. \u0027Why was this written?\u0027 identifies purpose, \u0027Who will read this?\u0027 identifies audience, and \u0027How is this organized?\u0027 identifies structure. These three clues help you analyze any genre.","feedbackIncorrect":"Not quite. Purpose is about what the writer wants to achieve, audience is about who the text is for, and structure is about how the text is organized. Use those three clues to match each detective question correctly.","t":"match","pairs":[{"a":"Why was this written?","b":"Purpose"},{"a":"Who will read this?","b":"Audience"},{"a":"How is this organized?","b":"Structure"}]},{"q":"Which statement best explains translanguaging in academic writing?","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Using only English from the start so that your ideas stay academically correct","correct":false},{"html":"Checking one difficult English word with a tool before finishing your paragraph","correct":false},{"html":"Writing the entire final draft in your home language before changing every sentence to English","correct":false},{"html":"Using all of your languages to think, plan, and make meaning before writing in English","correct":true}]},{"q":"Which sentence is the closing link in a paragraph about study habits?","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Therefore, setting a regular study time helps students stay organized each week.","correct":true},{"html":"A regular schedule reduces decision fatigue and makes homework easier to begin.","correct":false},{"html":"A regular study routine improves students’ focus and time management.","correct":false},{"html":"For example, a student who studies at the same time daily may miss fewer deadlines.","correct":false}]},{"q":"A student is given a short text and wants to identify its genre. Which question best helps the student identify the audience of the text?","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Why was it written?","correct":false},{"html":"How is it organized?","correct":false},{"html":"Who will read it?","correct":true},{"html":"What example does it include?","correct":false}]},{"q":"Using your home language to plan ideas can support stronger writing in English.","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"False","correct":false},{"html":"True","correct":true}]},{"q":"A writer has finished a first draft and notices that one paragraph is out of order and another needs more support. What should the writer do next?","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Edit by correcting grammar, spelling, and punctuation in the draft first.","correct":false},{"html":"Plan by choosing a topic, audience, and purpose for the assignment again.","correct":false},{"html":"Draft by rewriting the entire paper into perfect sentences right away.","correct":false},{"html":"Revise by improving the paragraph order and adding support before editing.","correct":true}]},{"q":"What is the main purpose of freewriting when you start a piece of writing?","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"To correct grammar while developing each point","correct":false},{"html":"To write a strong introduction right away","correct":false},{"html":"To organize points into a clear writing map","correct":false},{"html":"To get ideas out without worrying about mistakes","correct":true}]},{"q":"Match each academic genre to the description that best identifies why it is written, who is expected to read it, and how it is usually organized. Focus on the function of each genre in academic writing, not just on familiar words in the label.","feedback":"","feedbackCorrect":"Correct. Each genre is identified by more than its name: its purpose explains why it is written, its audience shows who it addresses, and its structure shows how the writing is organized.","feedbackIncorrect":"Incorrect. The best matches depend on three features working together: the genre\u0027s purpose, the audience it is meant for, and the structure readers expect. Review how each academic genre is composed for a specific situation.","t":"match","pairs":[{"a":"Research abstract","b":"Written for instructors, researchers, or students who need a quick overview of a study; it typically moves through background, aim, method, results, and conclusion."},{"a":"Summary response","b":"Written for a teacher or classmates to show understanding of a source and add a response; it usually presents the main points first and then evaluates or comments on them."},{"a":"Five-paragraph essay","b":"Written mainly for an instructor to develop one central claim; it often follows an introduction, three body paragraphs with support, and a concluding paragraph."},{"a":"Annotated bibliography","b":"Written for researchers or students collecting sources on a topic; it is usually organized as a list of citations, each followed by a brief description and evaluation of the source."},{"a":"Lab report","b":"Written for an instructor or scientific audience to document an experiment; it commonly includes purpose, materials or method, results, and discussion."},{"a":"Discussion board post","b":"Written for classmates and the instructor in an online course space; it usually states an initial idea, supports it briefly, and may invite or respond to further discussion."}]},{"q":"Match each step in the translanguaging brainstorming process with the action that belongs to it. Focus on what the writer does during planning before writing in English.","feedback":"","feedbackCorrect":"Correct. The process begins with generating ideas in any language, then organizing them, then selecting English key terms, and finally using those notes to write a first English version.","feedbackIncorrect":"Not quite. Each step has a different job: brainstorming generates ideas, sorting organizes them, choosing key terms identifies the main English vocabulary, and drafting in English turns the notes into first sentences and paragraphs.","t":"match","pairs":[{"a":"Brainstorm freely","b":"Write everything you know about the topic in any language or by mixing languages without stopping to judge the ideas."},{"a":"Sort your ideas","b":"Group related notes together and remove repeated ideas so the plan becomes clearer."},{"a":"Choose key terms","b":"Find the main English words or phrases for the most important ideas in the notes and check meaning in context."},{"a":"Draft in English","b":"Use the notes to write a first version in English, beginning with one clear sentence instead of translating word for word."}]},{"q":"Good writers move back and forth between the stages of the writing process as their ideas change.","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"True","correct":true},{"html":"False","correct":false}]},{"q":"A new student is planning one paragraph about why academic writing feels difficult. Which option best identifies the common challenges the student should include?","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Strong grammar, long readings, and strict deadlines","correct":false},{"html":"Hidden rules, new language, and lack of process","correct":true},{"html":"Hidden rules, better vocabulary, and one final draft","correct":false},{"html":"Clear rules, new language, and regular practice","correct":false}]},{"q":"A student is drafting an academic essay in English and uses an AI tool to suggest clearer wording for sentences the student has already written. Which use of AI best shows the student is treating AI as a writing partner rather than a ghostwriter?","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"The student uses AI to improve wording but keeps their own ideas, decisions, and final draft.","correct":true},{"html":"The student copies AI-generated paragraphs into the essay because the ideas match the assignment topic.","correct":false},{"html":"The student asks AI to write the full essay and then submits it after a quick review.","correct":false},{"html":"The student uses AI to choose the topic and develop every main point before writing begins.","correct":false}]},{"q":"A student writes a first draft of an academic paragraph, rereads it, reorganizes the ideas, adds support, and then edits the final version. What does this show about writing?","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Writing is a planning activity that ends once the main ideas are listed clearly.","correct":false},{"html":"Writing is a recursive process that moves between drafting, revising, and finalizing.","correct":true},{"html":"Writing is a linear process that should be completed in one draft before editing.","correct":false},{"html":"Writing is mainly a proofreading task that focuses on correcting grammar at the end.","correct":false}]},{"q":"A learner is completing the diagnostic writing assignment. Which sequence shows the correct process from beginning to end?","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Plan, revise, draft, rest, check, submit","correct":false},{"html":"Draft, plan, revise, check, rest, submit","correct":false},{"html":"Plan, draft, check, submit, rest, revise","correct":false},{"html":"Plan, draft, rest, revise, check, submit","correct":true}]},{"q":"A strong paragraph has four parts: a topic sentence, support, an example, and a __________.","feedback":"","feedbackCorrect":"Correct. A closing link is the final part of a well-formed paragraph. It finishes the idea and may help prepare the reader for the next paragraph without adding a new idea.","feedbackIncorrect":"Incorrect. The missing term is \"closing link.\" In the lesson, a strong paragraph includes a topic sentence, support, an example, and a closing link. This last part wraps up the point and shows why it matters or leads to what comes next.","t":"fill","accepted":["closing link"]},{"q":"Which statement best explains the idea that academic writing is a skill, not a talent?","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"It is strongest when writers finish one draft quickly and submit it unchanged.","correct":false},{"html":"It can improve when writers learn and use helpful steps, practice, and revision.","correct":true},{"html":"It depends mainly on using advanced English words from the beginning.","correct":false},{"html":"It comes mostly from having a natural gift that other writers cannot learn.","correct":false}]}]},{"title":"Assignment: Genre Detective","kind":"lesson","intro":"","passingScore":null,"blocks":[{"t":"note","html":"\u003cp\u003e\u003cstrong\u003eTask\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eChoose one short abstract from an open-access article. In 150 to 200 words, explain its purpose, its audience, and its structure. Use your own words, and give at least one example from the abstract to support each point.\u003c/p\u003e"},{"t":"process","items":[{"kind":"intro","title":"Choose an abstract","html":"\u003cp\u003e\u003cem\u003eLook in an open-access journal or database in a field you know. Pick an abstract that is short enough to read twice in a few minutes.\u003c/em\u003e\u003c/p\u003e"},{"kind":"step","title":"Read it twice","html":"\u003cp\u003eRead once to understand the main idea. Read again and notice how the writer moves from background to results.\u003c/p\u003e"},{"kind":"step","title":"Answer the three questions","html":"\u003cp\u003eTake brief notes: What is the purpose? Who is the audience? How is it organized?\u003c/p\u003e"},{"kind":"step","title":"Write 150 to 200 words","html":"\u003cp\u003eUse one short paragraph or three. Explain each point and support it with an example from the abstract.\u003c/p\u003e"},{"kind":"step","title":"Check your work","html":"\u003cp\u003e\u003cem\u003eUse the checklist below. Read your response aloud to catch unclear sentences.\u003c/em\u003e\u003c/p\u003e"},{"kind":"summary","title":"Submit","html":"\u003cp\u003e\u003cem\u003ePaste your response into the submission form below.\u003c/em\u003e\u003c/p\u003e"}]},{"t":"button","label":"Submit here","desc":"Submit your Genre Detective response","href":"mailto:wemimoaluko@gmail.com"},{"t":"divider"}]},{"title":"Module 3: The Library and Builder\u0027s Floor","kind":"section","intro":"","passingScore":null,"blocks":[]},{"title":"3.1 Using sources without losing your voice","kind":"lesson","intro":"","passingScore":null,"blocks":[{"t":"text","level":2,"heading":"Learning goal","html":"\u003cp\u003eBy the end of this lesson, you will be able to summarize and paraphrase a source in your own words, avoid plagiarism, and cite the source in APA 7 style.\u003c/p\u003e"},{"t":"text","level":2,"heading":"Why we use sources","html":"Academic writers do not work alone. They build on the ideas of other researchers, and they show their readers where those ideas came from. Using sources makes your writing more trustworthy, because your reader can see the evidence behind your claims. The challenge is to use other people’s ideas while keeping your own voice. This lesson shows you how."},{"t":"flashcards","items":[{"front":"Summary","back":"\u003cp\u003eA short version of a source that includes only its main points, written entirely in your own words. A summary is much shorter than the original.\u003c/p\u003e"},{"front":"Paraphrase","back":"\u003cp\u003eA restatement of one idea from a source in your own words and your own sentence structure. A paraphrase is about the same length as the original idea.\u003c/p\u003e"},{"front":"Quotation","back":"\u003cp\u003eThe exact words of a source, placed inside quotation marks. Use quotations rarely, and only when the exact wording matters.\u003c/p\u003e"},{"front":"Plagiarism","back":"\u003cp\u003eUsing someone else’s words or ideas without giving credit. It includes copying text, changing only a few words, and forgetting to cite a paraphrase.\u003c/p\u003e"}]},{"t":"process","items":[{"kind":"intro","title":"How to paraphrase in five steps","html":"Lorem ipsum dolor sit amet, consectetur adipiscing elit. In purus velit, tincidunt ac nibh quis, sollicitudin varius libero. Nullam at mi felis. Donec a scelerisque augue, sit amet porttitor nibh. Suspendisse at lorem ut elit placerat blandit."},{"kind":"step","title":"Read until you understand","html":"Read the passage more than once. If you cannot explain it to a friend in simple words, read it again or look up difficult terms."},{"kind":"step","title":"Close the source","html":"Put the text away, or cover it. Writing from memory forces you to use your own words and your own sentence structure."},{"kind":"step","title":"Write the idea","html":"Explain the idea in your own words as if you were telling a classmate. Do not worry about perfect sentences yet."},{"kind":"step","title":"Compare and fix","html":"Open the source again. Check that your meaning is accurate and that you did not copy phrases or follow the original sentence structure too closely."},{"kind":"step","title":"Cite the source","html":"Add an in-text citation. A paraphrase still needs credit, because the idea belongs to the original author."},{"kind":"summary","title":"Summary","html":"1. Read until you understand. 2. Close the source. 3. Write the idea. 4. Compare and fix. 5. Cite the source."}]},{"t":"tabs","items":[{"title":"In-text Citation","html":"Place the author’s last name and the year in parentheses, for example (Rivera, 2023). You can also build the author into your sentence: Rivera (2023) explains that revision improves clarity. For a direct quotation, add the page number: (Rivera, 2023, p. 47)."},{"title":"Reference Entry","html":"At the end of your text, list each source in a reference list. A journal article follows this pattern: Author, A. A. (Year). Title of the article in sentence case. Journal Name in Italics, volume in italics(issue), pages. DOI link. Example for practice (invented): Rivera, M. (2023). Feedback and revision in multilingual classrooms. Journal of Writing Studies, 14(2), 45-60."},{"title":"Common Mistakes","html":"Forgetting to cite a paraphrase, citing in the text without listing the source in the references, and listing sources in the references that you never used in the text. Check that every in-text citation has a matching reference entry."}]},{"t":"sorting","piles":["Acceptable paraphrase","Plagiarism"],"items":[{"html":"Writers who return to their work and improve it over several versions usually co","pile":0},{"html":"Students who revise their writing across several drafts tend to produce clearer","pile":1},{"html":"Writers who return to their work and improve it over several versions usually co","pile":1}]},{"q":"Which is the best way to include another author’s idea in your essay?","feedback":"","feedbackCorrect":"Yes. A paraphrase in your own words, plus a citation, respects the author and shows your reader where the idea came from.","feedbackIncorrect":"Look again. Changing a few words is still plagiarism, and any idea that comes from a source needs a citation, even when you rewrite it.","t":"choice","multi":false,"answers":[{"html":"Copy the sentence and change two words.","correct":false},{"html":"Explain the idea in your own words and add an in-text citation.","correct":true},{"html":"Use the idea without mentioning the author, since it is common knowledge.","correct":false},{"html":"Paste the sentence without quotation marks.","correct":false}],"check":true},{"t":"note","html":"Try it (15 minutes)\u003cbr\u003e\u003cbr\u003eChoose one sentence from an open-access article. Use the five steps to paraphrase it. Then write an in-text citation in APA 7 style. Finally, compare your version with the original. If the structure still looks too similar, rewrite it once more."},{"t":"list","style":"number","items":["A summary is short and covers main points.","A paraphrase restates one idea at about the same length.","A paraphrase needs your own words, your own sentence structure, and a citation.","Every in-text citation needs a matching entry in the reference list."]},{"t":"divider"}]},{"title":"3.2 AI as a writing partner","kind":"lesson","intro":"","passingScore":null,"blocks":[{"t":"text","level":2,"heading":"\u003cstrong\u003eLearning goal\u003c/strong\u003e","html":"\u003cp\u003eBy the end of this lesson, you will be able to decide when AI tools can support your writing and when they cannot, and keep a short decision log that shows your own thinking.\u003c/p\u003e"},{"t":"text","level":2,"heading":"","html":"AI writing tools can explain a rule, suggest ideas, and point out possible errors. They can also produce smooth text that is not yours, repeat mistakes, and invent facts. In academic writing, you are responsible for every idea and sentence you submit. Treat AI as a partner that helps you think, not as a substitute for your own writing. Always follow your instructor’s or institution’s rules on AI use."},{"t":"accordion","items":[{"title":"Invented sources","html":"AI tools can produce references that look real but do not exist. Never copy a reference without finding the source yourself and checking the title, authors, and year."},{"title":"Loss of your voice","html":"AI text can sound polished but generic. If you accept it without change, your writing will not show your own thinking, and your instructor may not be able to assess your progress."},{"title":"Policy violations","html":"Many courses allow some AI uses and forbid others. In this course, AI is for brainstorming, grammar checking after you have written a draft, and idea exploration, never for writing a text you submit as your own."}]},{"t":"sorting","piles":["Acceptable","Not acceptable"],"items":[{"html":"Asking AI to explain the difference between “who” and “whom”","pile":0},{"html":"Brainstorming possible topics for a paragraph","pile":0},{"html":"Checking your own finished draft for grammar suggestions, then deciding which to","pile":0},{"html":"Asking AI to write your paragraph and submitting it","pile":1},{"html":"Copying an AI-generated reference list without checking the sources","pile":1},{"html":"Using AI for the Module 1 diagnostic task","pile":1}]},{"t":"process","items":[{"kind":"intro","title":"Your decision log in four steps","html":"Follow these four steps to keep a clear record of your decisions when using a tool."},{"kind":"step","title":"Note what you asked","html":"Write down the question or request you gave the tool, in one sentence."},{"kind":"step","title":"Note what it suggested","html":"Summarize the answer or paste the key part into your log."},{"kind":"step","title":"Decide what to keep","html":"Choose which suggestions you will use, change, or reject. Use your own judgment and your knowledge of the topic."},{"kind":"step","title":"Explain your choice","html":"Write one sentence about why. Explaining a choice shows that the final writing is yours."},{"kind":"summary","title":"Keep your decision log clear","html":"By following these steps, you ensure your decisions are well-documented and clearly your own."}]},{"t":"tabs","items":[{"title":"Request","html":"“Can you suggest linking words for showing contrast?”"},{"title":"Suggestion","html":"The tool listed “however,” “although,” “on the other hand,” and “in contrast.”"},{"title":"Decision","html":"I used “however” in sentence 3 and kept my own wording elsewhere."},{"title":"Reason","html":"“However” fits a formal academic tone, and the other options were too long for my sentence."}]},{"q":"Which are responsible uses of AI in this course? Select all that apply.","feedback":"You may use AI to learn and to check, but not to replace your writing, and you must verify any source the tool gives you.","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":true,"answers":[{"html":"Asking for an explanation of a grammar rule","correct":true},{"html":"Checking a reference the tool suggested by finding the real source","correct":true},{"html":"Submitting a paragraph the tool wrote for you","correct":false},{"html":"Copying a reference list from the tool without checking it","correct":false}],"check":true},{"t":"note","html":"\u003cstrong\u003eTry it (10 minutes)\u003c/strong\u003e\u003cbr\u003e\u003cbr\u003eThink of one way AI could help you with your next writing task. Write a decision log entry with the four parts: request, suggestion, decision, reason. If you do not use a tool, imagine the request and write what you would keep or reject."},{"t":"text","level":3,"heading":"\u003cstrong\u003eKey ideas\u003c/strong\u003e","html":""},{"t":"list","style":"number","items":["AI is a partner for thinking and checking, not a writer for your final text.","Always verify sources and facts that an AI tool gives you.","A short decision log shows your own thinking and keeps your use of AI honest."]},{"t":"divider"}]},{"title":"3.3 Building the essay","kind":"lesson","intro":"","passingScore":null,"blocks":[{"t":"text","level":2,"heading":"\u003cstrong\u003eLearning goal\u003c/strong\u003e","html":"\u003cp\u003eBy the end of this lesson, you will be able to write a clear thesis statement and plan an essay with an introduction, body paragraphs, and a conclusion.\u003c/p\u003e"},{"t":"text","level":2,"heading":"From paragraph to essay","html":"An essay is a group of paragraphs working together to support one main argument. Each paragraph you learned to write in Module 2 becomes a building block. A good essay has three parts: an introduction that prepares the reader, body paragraphs that develop your ideas, and a conclusion that leaves the reader with a clear final thought. The glue that holds everything together is your thesis statement."},{"t":"process","items":[{"kind":"intro","title":"The essay blueprint","html":"A step-by-step guide to structuring an effective essay, from introduction to conclusion."},{"kind":"step","title":"Introduction","html":"Begin with a hook, such as a question, a surprising fact, or a short scene. Add a little background so the reader understands the topic. End with your thesis statement."},{"kind":"step","title":"Body Paragraphs","html":"Write one paragraph for each main point. Each paragraph starts with a topic sentence that supports your thesis and includes support, an example, and a closing link."},{"kind":"step","title":"Counterargument (for argumentative essays)","html":"Briefly present a different view, then explain why your position is still stronger. This shows fairness and strengthens your argument."},{"kind":"step","title":"Conclusion","html":"Restate your thesis in new words, summarize your main points, and end with a final thought about why the topic matters. Do not introduce a new argument."},{"kind":"summary","title":"Essay Structure Summary","html":"Follow these steps to organize your essay clearly and persuasively."}]},{"t":"tabs","items":[{"title":"Descriptive or Expository","html":"Explains a topic clearly without arguing for a position.\u003cbr\u003e\u003cbr\u003e\u003cstrong\u003eStructure:\u003c/strong\u003e Introduction with a controlling idea, body paragraphs that explain different parts, and a conclusion."},{"title":"Argumentative","html":"Takes a position and defends it with reasons and evidence.\u003cbr\u003e\u003cbr\u003e\u003cstrong\u003eStructure:\u003c/strong\u003e Introduction with a debatable thesis, body paragraphs with reasons, a counterargument, and a conclusion."},{"title":"Compare and Contrast","html":"Examines the similarities and differences between two things.\u003cbr\u003e\u003cbr\u003e\u003cstrong\u003eStructure:\u003c/strong\u003e Either block (all of A, then all of B) or point-by-point (each point compares A and B)."}]},{"t":"accordion","items":[{"title":"Weak Thesis Statement","html":"“Online learning is a topic many people discuss.” This states no position and gives no direction."},{"title":"Better Thesis Statement","html":"“Online learning is helpful for students.” This takes a position, but it is vague."},{"title":"Best Thesis Statement","html":"“Online learning gives working adults the flexibility to study while earning an income, but it requires strong self-discipline to succeed.” This is specific, debatable, and previews the essay’s main points."}]},{"t":"sorting","piles":["Introduction","Body","Conclusion"],"items":[{"html":"A hook question","pile":0},{"html":"The thesis statement","pile":0},{"html":"A topic sentence for one main point","pile":1},{"html":"An example that supports a reason","pile":1},{"html":"The thesis restated in new words","pile":2},{"html":"A final thought about why the topic matters","pile":2}]},{"q":"Which is the strongest thesis statement?","feedback":"","feedbackCorrect":"Yes. This thesis is specific, takes a position, and tells the reader what the essay will discuss.","feedbackIncorrect":"Look again. A strong thesis is specific and debatable. Statements that are too broad, too vague, or only personal opinion do not give your essay a clear direction.","t":"choice","multi":false,"answers":[{"html":"Social media is popular.","correct":false},{"html":"Social media has good and bad points.","correct":false},{"html":"Social media helps students share ideas, but it can also reduce study time when used without limits.","correct":true},{"html":"I think social media is interesting.","correct":false}],"check":true},{"t":"note","html":"\u003cstrong\u003eTry it (20 minutes)\u003c/strong\u003e\u003cbr\u003eChoose a topic for your final essay. Write a thesis statement that is specific and debatable. Then plan your essay: list three main points for the body, and add one example or reason for each. Save your plan. You will use it in Module 4."},{"t":"text","level":3,"heading":"\u003cstrong\u003eKey ideas\u003c/strong\u003e","html":""},{"t":"list","style":"number","items":["An essay has an introduction, body paragraphs, and a conclusion, all tied to one thesis.","A strong thesis is specific, debatable, and previews your main points.","Each body paragraph follows the paragraph pattern from Module 2."]},{"t":"divider"}]},{"title":"Module 3 Self-Check","kind":"quiz","intro":"\u003cp\u003eQuiz\u003c/p\u003e","passingScore":80,"blocks":[{"q":"What is patchwriting?","feedback":"Patchwriting is a form of plagiarism, even if you cite the source.","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Writing a summary in your own words","correct":false},{"html":"Copying a source and changing only a few words","correct":true},{"html":"Using a quotation with quotation marks","correct":false},{"html":"Citing a source in APA style","correct":false}]},{"q":"What should you do after reading a passage you want to paraphrase?","feedback":"Writing from memory helps you use your own words, and you still need to cite.","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Copy the sentence and replace some words","correct":false},{"html":"Close the source and write the idea from memory in your own words","correct":true},{"html":"Skip the citation if you changed the words","correct":false},{"html":"Keep the original sentence structure","correct":false}]},{"q":"Which is a correct APA 7 in-text citation?","feedback":"APA in-text citations give the author\u0027s last name and the year.","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"(2023, Rivera)","correct":false},{"html":"(Rivera, 2023)","correct":true},{"html":"Rivera 2023 says","correct":false},{"html":"[Rivera: 2023]","correct":false}]},{"q":"An AI tool gives you a reference for your essay. What should you do?","feedback":"AI tools can invent references. You are responsible for checking every source.","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Copy it into your reference list","correct":false},{"html":"Find the real source and check the details before using it","correct":true},{"html":"Delete the in-text citation","correct":false},{"html":"Use it only if it looks professional","correct":false}]},{"q":"Which part of an essay contains the thesis statement?","feedback":"The thesis usually appears at the end of the introduction.","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"The last body paragraph","correct":false},{"html":"The introduction","correct":true},{"html":"The reference list","correct":false},{"html":"The title page","correct":false}]},{"q":"Which thesis is the strongest?","feedback":"A strong thesis is specific, debatable, and previews the main points.","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Technology is important.","correct":false},{"html":"I like technology.","correct":false},{"html":"Technology helps students research faster, but it can reduce deep reading when used without limits.","correct":true},{"html":"Many people use technology.","correct":false}]}]},{"title":"Assignment: Source Summary","kind":"lesson","intro":"","passingScore":null,"blocks":[{"t":"text","level":2,"heading":"Task","html":"\u003cp\u003eChoose one short open-access article and write a summary of 150 to 200 words in your own words. Include at least one in-text citation and a complete reference entry in APA 7 style. If you used an AI tool for any part of the task, add your decision log.\u003c/p\u003e"},{"t":"process","items":[{"kind":"intro","title":"How to Summarize an Article","html":"Follow these steps to effectively summarize an article and ensure proper citation."},{"kind":"step","title":"Choose an article","html":"Pick a short, open-access article or a section of one in a field you know. Make sure you can read it comfortably in about 20 minutes."},{"kind":"step","title":"Read and note the main points","html":"Highlight or list three to five main ideas. Leave out small details and examples."},{"kind":"step","title":"Write your summary","html":"Close the article and write from your notes in your own words. Aim for 150 to 200 words."},{"kind":"step","title":"Add citations","html":"Place an in-text citation with the author’s last name and year. Then add a complete reference entry at the end."},{"kind":"step","title":"Check your work","html":"Use the checklist below. Compare your summary with the article to confirm that you used your own words and structure."},{"kind":"step","title":"Submit","html":"Paste your summary, reference entry, and optional decision log into the submission form."},{"kind":"summary","title":"Summary of the Process","html":"By following these steps, you can create a concise, well-cited summary of any article."}]},{"t":"list","style":"number","items":["My summary is 150 to 200 words.","I used my own words and sentence structure.","I included an in-text citation in (Author, Year) form.","I included a complete reference entry in APA 7 style.","If I used AI, I included a decision log."]},{"t":"text","level":2,"heading":"","html":"Click the button below to open the submission form."},{"t":"button","label":"Submit here","desc":"\u003cstrong\u003eLocation 1\u003c/strong\u003e\u003cbr\u003eClick the button to open the submission form","href":"mailto:wemimoaluko@gmail.com"},{"t":"divider"}]},{"title":"Module 4: The Gallery","kind":"section","intro":"","passingScore":null,"blocks":[]},{"title":"4.1 Types of feedback","kind":"lesson","intro":"","passingScore":null,"blocks":[{"t":"text","level":2,"heading":"Learning goal","html":"\u003cp\u003eBy the end of this lesson, you will be able to recognize the main types of feedback on writing, understand what each one is asking you to do, and notice common patterns in your own errors.\u003c/p\u003e"},{"t":"text","level":2,"heading":"Why feedback matters","html":"\u003cp\u003eFeedback shows you how a real reader experiences your writing. It can point out gaps you cannot see yourself, because you already know what you meant. Feedback works best when you understand it and act on it. Not all feedback looks the same: some comments correct a mistake for you, some only point to where the problem is, and some explain a rule. Knowing the difference helps you respond to each comment in the right way.\u003c/p\u003e"},{"t":"text","level":3,"heading":"Four kinds of feedback","html":""},{"t":"tabs","items":[{"title":"Direct","html":"\u003cp\u003eThe reader writes the correct form for you. Example: “I saw dog” becomes “I saw a dog.” This is quick and clear, and it is helpful when a form is new or difficult for you.\u003c/p\u003e"},{"title":"Indirect","html":"\u003cp\u003eThe reader marks the error but does not correct it, for example by underlining, circling, or placing a symbol. Example: “I saw dog” with the word “dog” underlined. You must decide what is wrong and fix it, which builds independence.\u003c/p\u003e"},{"title":"Metalinguistic","html":"\u003cp\u003eThe reader gives a rule, code, or short explanation. Example: “Article missing: use \u0026#8216;a\u0026#8217; before a singular countable noun.” This helps you understand the pattern so that you can avoid the same error later.\u003c/p\u003e"},{"title":"Ideas and organization","html":"\u003cp\u003eThe reader comments on content and structure, not grammar. Example: “Add an example to support this point.” This kind of feedback matters most in early drafts, because it affects the whole paragraph.\u003c/p\u003e"}]},{"t":"text","level":3,"heading":"Which feedback helps when?","html":""},{"t":"accordion","items":[{"title":"Direct feedback","html":"\u003cp\u003eMost helpful when you are meeting a form for the first time, when the error is complex, or when you are close to a deadline and need a clear model.\u003c/p\u003e"},{"title":"Indirect feedback","html":"\u003cp\u003eMost helpful when you already know the rule but missed the error. Finding and fixing it yourself helps you remember it.\u003c/p\u003e"},{"title":"Metalinguistic feedback","html":"\u003cp\u003eMost helpful when the same error keeps returning. An explanation helps you see the pattern and apply the rule in new sentences.\u003c/p\u003e"},{"title":"Ideas and organization feedback","html":"\u003cp\u003eMost helpful on first and second drafts. Fix these problems first, because changing a paragraph may remove sentences you would have edited.\u003c/p\u003e"}]},{"t":"text","level":3,"heading":"Which type is it?","html":"\u003cp\u003eInstruction: Drag each comment to the type of feedback it represents.\u003c/p\u003e"},{"t":"sorting","piles":["Direct","Indirect","Metalinguistic","Ideas and organization"],"items":[{"html":"“I saw dog” corrected to “I saw a dog.”","pile":0},{"html":"The word “dog” underlined with no comment.","pile":1},{"html":"“Article missing: use \u0026#8216;a\u0026#8217; before a singular countable noun.”","pile":2},{"html":"“Add an example to support your second point.”","pile":3}]},{"q":"A teacher underlines “He go to school” but does not correct it. What type of feedback is this?","feedback":"","feedbackCorrect":"\u003cp\u003eYes. The teacher marks where the problem is, and you decide how to fix it.\u003c/p\u003e","feedbackIncorrect":"\u003cp\u003eLook again. The teacher did not write the correction or explain a rule. They only showed where the error is.\u003c/p\u003e","t":"choice","multi":false,"answers":[{"html":"Direct","correct":false},{"html":"Indirect","correct":true},{"html":"Metalinguistic","correct":false},{"html":"Ideas and organization","correct":false}],"check":true},{"q":"Instruction: Match each sentence to the type of pattern it shows.","feedback":"","feedbackCorrect":"","feedbackIncorrect":"","t":"match","check":true,"pairs":[{"a":"“I saw dog yesterday.”","b":"Articles"},{"a":"“I have been to school yesterday.”","b":"Verb tense"},{"a":"“She is good in math.”","b":"Prepositions"},{"a":"“Students study hard. Students pass exams.”","b":"Linking ideas (cohesion)"}]},{"t":"note","html":"\u003cp\u003e\u003cstrong\u003eTry it (10 minutes)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eLook at the feedback you have received on any piece of writing: from a teacher, a classmate, or a tool. Choose three comments. For each one, write its type (direct, indirect, metalinguistic, or ideas and organization) and what it asks you to do.\u003c/p\u003e"},{"t":"text","level":3,"heading":"\u003cstrong\u003eKey ideas\u003c/strong\u003e","html":""},{"t":"list","style":"number","items":["\u003cp\u003eDirect, indirect, and metalinguistic feedback each help in different ways.\u003c/p\u003e","\u003cp\u003eFeedback on ideas and organization comes first in early drafts.\u003c/p\u003e","\u003cp\u003eNoticing patterns in your errors helps you improve faster than fixing one sentence at a time.\u003c/p\u003e"]},{"t":"divider"}]},{"title":"4.2 Revising with a Feedback Diary","kind":"lesson","intro":"","passingScore":null,"blocks":[{"t":"text","level":2,"heading":"Learning goal","html":"\u003cp\u003eBy the end of this lesson, you will be able to revise a text using feedback, keep a Feedback Diary to track your patterns, and give kind, specific feedback to another writer.\u003c/p\u003e"},{"t":"text","level":2,"heading":"Feedback works only when you use it","html":"\u003cp\u003eReceiving feedback is only the first step. Real improvement comes from what you do next. In this lesson, you will learn a simple routine for turning comments into a better draft, a tool for tracking your progress over time, and a way to give useful feedback to others. Giving feedback also improves your own writing, because you begin to notice what makes a text clear.\u003c/p\u003e"},{"t":"text","level":3,"heading":"Revise with feedback in five steps","html":""},{"t":"process","items":[{"kind":"step","title":"Read all the feedback once","html":"\u003cp\u003eDo not change anything yet. Read every comment to understand the overall message. Feeling surprised or disappointed is normal, so take a short break if you need one.\u003c/p\u003e"},{"kind":"step","title":"Sort the comments","html":"\u003cp\u003ePut each comment into one of three groups: ideas, organization, or language. This stops you from fixing small errors in a paragraph you may need to rewrite.\u003c/p\u003e"},{"kind":"step","title":"Revise ideas and structure first","html":"\u003cp\u003eAdd missing support, move paragraphs, and remove anything off topic. Make the big changes before the small ones.\u003c/p\u003e"},{"kind":"step","title":"Fix language patterns","html":"\u003cp\u003eNow correct grammar, word choice, and punctuation. When you find the same error more than once, look for the rule behind it.\u003c/p\u003e"},{"kind":"step","title":"Record it in your diary","html":"\u003cp\u003eWrite what changed and what you learned. This step turns one correction into long-term learning.\u003c/p\u003e"}]},{"t":"text","level":3,"heading":"Your Feedback Diary","html":""},{"t":"tabs","items":[{"title":"What it is","html":"\u003cp\u003eA simple table or notebook where you record the feedback you receive, the pattern it shows, and what you changed. Over time, you will see which errors appear less often and which still need attention.\u003c/p\u003e"},{"title":"Columns to use","html":"\u003cp\u003eDate, Comment received, Type of feedback, Pattern (for example articles or tense), What I changed, Next time I will.\u003c/p\u003e"},{"title":"Example entry","html":"\u003cp\u003eDate: Oct 20. Comment: “Article missing before \u0026#8216;student.\u0026#8217;” Type: Indirect. Pattern: Articles. What I changed: “A student may avoid speaking.” Next time I will: check singular nouns for a, an, or the before I submit.\u003c/p\u003e"}]},{"t":"text","level":3,"heading":"Giving feedback: the Revision Relay","html":""},{"t":"accordion","items":[{"title":"Comment 1: Ideas","html":"\u003cp\u003eStart with the ideas. Say what you understood and what is strong, then suggest one change. Example: “I like your example about sleep. Could you add one more reason in the support?”\u003c/p\u003e"},{"title":"Comment 2: Organization","html":"\u003cp\u003eComment on order and links. Example: “The second sentence feels like a jump. A linking word such as \u0026#8216;however\u0026#8217; could help me follow.”\u003c/p\u003e"},{"title":"Comment 3: Language","html":"\u003cp\u003eChoose one or two language patterns, not every error. Example: “I noticed that some singular nouns have no article. Check the first two sentences.”\u003c/p\u003e"},{"title":"Tips for kind feedback","html":"\u003cp\u003eBe specific, be respectful, and offer a way to improve. Write comments you would be happy to receive yourself.\u003c/p\u003e"}]},{"t":"text","level":3,"heading":"Helpful or unhelpful?","html":"\u003cp\u003eInstruction: Drag each comment into the group that fits.\u003c/p\u003e"},{"t":"sorting","piles":["Helpful","Unhelpful"],"items":[{"html":"“Your second paragraph needs an example to support your point.”","pile":0},{"html":"“Try adding \u0026#8216;however\u0026#8217; to show the contrast in sentence three.”","pile":0},{"html":"“Bad.”","pile":1},{"html":"“Fix the grammar.”","pile":1}]},{"q":"You receive feedback on your draft. What should you do first?","feedback":"","feedbackCorrect":"\u003cp\u003eYes. Reading everything first helps you see the main message and set priorities before you start changing.\u003c/p\u003e","feedbackIncorrect":"\u003cp\u003eLook again. Acting on comments one by one can waste time. Understand the whole message first, then plan your revision.\u003c/p\u003e","t":"choice","multi":false,"answers":[{"html":"Fix every grammar error immediately","correct":false},{"html":"Read all the feedback once without making changes","correct":true},{"html":"Ignore the comments you disagree with","correct":false},{"html":"Rewrite the whole draft","correct":false}],"check":true},{"t":"note","html":"\u003cp\u003e\u003cstrong\u003eTry it (20 minutes)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eTake your diagnostic paragraph from Module 1. Read it as if you were someone else and write three comments: one on ideas, one on organization, and one on language. Revise the paragraph using your own comments. Then add one entry to a Feedback Diary using the columns above.\u003c/p\u003e"},{"t":"text","level":3,"heading":"\u003cstrong\u003eKey ideas\u003c/strong\u003e","html":""},{"t":"list","style":"number","items":["\u003cp\u003eRead all feedback first, then revise ideas and structure before language.\u003c/p\u003e","\u003cp\u003eA Feedback Diary shows patterns in your writing and helps you track progress.\u003c/p\u003e","\u003cp\u003eGood feedback is specific, kind, and gives the writer a next step.\u003c/p\u003e"]},{"t":"divider"}]},{"title":"4.3 Final essay and showcase","kind":"lesson","intro":"","passingScore":null,"blocks":[{"t":"text","level":2,"heading":"Learning goal","html":"\u003cp\u003eBy the end of this lesson, you will be able to plan, draft, revise, and reflect on a final essay that shows what you have learned in this course.\u003c/p\u003e"},{"t":"text","level":2,"heading":"Putting it all together","html":"\u003cp\u003eYour final essay is the place where everything you learned comes together. You will use the writing process from Module 1, paragraph and genre skills from Module 2, sources and a thesis from Module 3, and feedback and revision from this module. The goal is not a perfect essay. The goal is a clear, well-built essay with a revision history that shows your growth.\u003c/p\u003e"},{"t":"text","level":3,"heading":"Your final essay journey","html":""},{"t":"process","items":[{"kind":"step","title":"Return to your plan","html":"\u003cp\u003eOpen the thesis statement and essay plan you wrote in Lesson 3.3. Check that your three main points still support your thesis.\u003c/p\u003e"},{"kind":"step","title":"Draft","html":"\u003cp\u003eWrite your introduction, body paragraphs, and conclusion. Use the paragraph pattern from Module 2 and add at least one source with an in-text citation.\u003c/p\u003e"},{"kind":"step","title":"Rest","html":"\u003cp\u003eSet your draft aside for a few hours, or overnight. Fresh eyes notice problems that tired eyes miss.\u003c/p\u003e"},{"kind":"step","title":"Revise with feedback","html":"\u003cp\u003eAsk a classmate or friend for feedback, or use your own comments. Fix ideas and structure first.\u003c/p\u003e"},{"kind":"step","title":"Edit","html":"\u003cp\u003eCheck grammar, spelling, citations, and your reference list. Review your Feedback Diary for patterns to watch for.\u003c/p\u003e"},{"kind":"step","title":"Reflect and submit","html":"\u003cp\u003eWrite a short revision note and reflection, then submit everything.\u003c/p\u003e"}]},{"t":"text","level":3,"heading":"Final essay checklist","html":""},{"t":"accordion","items":[{"title":"Ideas","html":"\u003cp\u003eMy thesis is specific and debatable. Each body paragraph supports it with reasons and examples.\u003c/p\u003e"},{"title":"Structure","html":"\u003cp\u003eMy essay has an introduction, body paragraphs, and a conclusion. Each paragraph has a topic sentence and a closing link.\u003c/p\u003e"},{"title":"Language","html":"\u003cp\u003eMy sentences are clear, my linking words help the reader, and I checked patterns from my Feedback Diary.\u003c/p\u003e"},{"title":"Sources","html":"\u003cp\u003eI paraphrased in my own words, used at least one in-text citation, and included a reference list in APA 7 style.\u003c/p\u003e"},{"title":"Integrity","html":"\u003cp\u003eThe writing is mine. If I used AI, I included my decision log and checked every source.\u003c/p\u003e"}]},{"t":"text","level":3,"heading":"Reflect on your growth","html":""},{"t":"tabs","items":[{"title":"Look back","html":"\u003cp\u003eReread your Module 1 diagnostic paragraph. What did you do well? What was difficult?\u003c/p\u003e"},{"title":"Look at now","html":"\u003cp\u003eCompare it with your final essay. What is stronger? Choose two or three specific changes.\u003c/p\u003e"},{"title":"Look ahead","html":"\u003cp\u003eWhat is one habit from this course that you will keep? What will you practice next?\u003c/p\u003e"}]},{"q":"Which items belong in your final submission? Select all that apply.","feedback":"\u003cp\u003eThe revision note and reflection show your process and growth, and the decision log keeps your use of AI honest. All four belong in your submission.\u003c/p\u003e","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":true,"answers":[{"html":"Your final essay","correct":true},{"html":"A short revision note describing what changed","correct":true},{"html":"Your reflection on growth","correct":true},{"html":"Your AI decision log, if you used an AI tool","correct":true}],"check":true},{"t":"note","html":"\u003cp\u003e\u003cstrong\u003eTry it (10 minutes)\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eStart your revision note now. In four or five sentences, describe one change you made after feedback, why you made it, and how it improved your writing. Keep it with your draft.\u003c/p\u003e"},{"t":"text","level":3,"heading":"\u003cstrong\u003eKey ideas\u003c/strong\u003e","html":""},{"t":"list","style":"number","items":["\u003cp\u003eA final essay combines process, genre, sources, and feedback.\u003c/p\u003e","\u003cp\u003eA revision note and reflection show your growth, not only your final text.\u003c/p\u003e","\u003cp\u003eKeep the habits that worked: planning, drafting, resting, revising, and tracking feedback.\u003c/p\u003e"]},{"t":"divider"}]},{"title":"Module 4 Self-Check","kind":"quiz","intro":"\u003cp\u003eModule 4 quiz\u003c/p\u003e","passingScore":80,"blocks":[{"q":"A teacher writes the correct form above your error. What type of feedback is this?","feedback":"\u003cp\u003eDirect feedback gives the correct form for you.\u003c/p\u003e","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Direct","correct":true},{"html":"Indirect","correct":false},{"html":"Metalinguistic","correct":false},{"html":"Peer feedback","correct":false}]},{"q":"Which feedback should you handle first in an early draft?","feedback":"\u003cp\u003eFix big issues first, because small edits may disappear when you rewrite.\u003c/p\u003e","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Spelling errors","correct":false},{"html":"Punctuation","correct":false},{"html":"Ideas and organization","correct":true},{"html":"Font and layout","correct":false}]},{"q":"What is the purpose of a Feedback Diary?","feedback":"\u003cp\u003eA diary helps you see patterns and measure improvement.\u003c/p\u003e","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"To record grades","correct":false},{"html":"To track feedback and patterns in your writing over time","correct":true},{"html":"To copy corrections from others","correct":false},{"html":"To list new vocabulary only","correct":false}]},{"q":"Which comment is the most helpful?","feedback":"\u003cp\u003eHelpful feedback is specific and gives the writer a next step.\u003c/p\u003e","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Bad.","correct":false},{"html":"Fix the grammar.","correct":false},{"html":"Your second paragraph needs an example to support your point.","correct":true},{"html":"I do not like it.","correct":false}]},{"q":"What should you do when you first receive feedback on a draft?","feedback":"\u003cp\u003eUnderstand the whole message first, then decide what to change.\u003c/p\u003e","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Correct every error right away","correct":false},{"html":"Read all the comments once, then plan your revision","correct":true},{"html":"Delete the draft","correct":false},{"html":"Ignore comments you do not like","correct":false}]},{"q":"Which item shows your growth in the final submission?","feedback":"\u003cp\u003eA revision note and reflection explain how and why your writing changed.\u003c/p\u003e","feedbackCorrect":"","feedbackIncorrect":"","t":"choice","multi":false,"answers":[{"html":"Only the final essay","correct":false},{"html":"A revision note and reflection","correct":true},{"html":"A list of grammar rules","correct":false},{"html":"The assignment instructions","correct":false}]}]},{"title":"Assignment: Final Essay and Showcase","kind":"lesson","intro":"","passingScore":null,"blocks":[{"t":"note","html":"\u003cp\u003e\u003cstrong\u003eTask\u003c/strong\u003e\u003c/p\u003e\u003cp\u003eWrite a final essay of 600 to 800 words, argumentative or expository, using the thesis and plan you made in Module 3. Include at least one source with an in-text citation and an APA 7 reference. Add a short revision note (100 to 150 words) and a reflection (200 to 250 words) comparing your Module 1 paragraph with your final essay.\u003c/p\u003e"},{"t":"text","level":3,"heading":"Steps","html":""},{"t":"process","items":[{"kind":"step","title":"Draft","html":"\u003cp\u003eWrite from your plan. Use the paragraph pattern and linking words from Module 2.\u003c/p\u003e"},{"kind":"step","title":"Rest and get feedback","html":"\u003cp\u003eWait a few hours, then ask a classmate or friend for feedback, or write feedback for yourself using the three-comment method.\u003c/p\u003e"},{"kind":"step","title":"Revise","html":"\u003cp\u003eFix ideas and structure first, then language. Record at least two entries in your Feedback Diary.\u003c/p\u003e"},{"kind":"step","title":"Check sources and integrity","html":"\u003cp\u003eVerify every citation and reference. If you used AI, attach your decision log.\u003c/p\u003e"},{"kind":"step","title":"Write your revision note and reflection","html":"\u003cp\u003eDescribe what changed and what you learned.\u003c/p\u003e"},{"kind":"step","title":"Submit","html":"\u003cp\u003eShare your work using the submission form.\u003c/p\u003e"}]},{"t":"text","level":3,"heading":"Checklist","html":""},{"t":"list","style":"check","items":["\u003cp\u003eMy essay is 600 to 800 words.\u003c/p\u003e","\u003cp\u003eMy thesis is specific and debatable.\u003c/p\u003e","\u003cp\u003eI used at least one source with an in-text citation and a reference entry.\u003c/p\u003e","\u003cp\u003eI wrote a revision note of 100 to 150 words.\u003c/p\u003e","\u003cp\u003eI wrote a reflection of 200 to 250 words.\u003c/p\u003e","\u003cp\u003eIf I used AI, I included my decision log.\u003c/p\u003e"]},{"t":"text","level":3,"heading":"Submit your work","html":"\u003cp\u003eBecause your essay is long, paste it into a Google Doc, set sharing to “Anyone with the link can comment,” and send the link.\u003c/p\u003e"},{"t":"button","label":"Submit your Final Essay","desc":"Include your Google Doc link, revision note, reflection, and (if you used AI) your decision log.","href":"mailto:wemimoaluko@gmail.com?subject=Final%20Essay%20and%20Showcase"},{"t":"text","level":3,"heading":"Optional: Gallery Share","html":"\u003cp\u003eWant to share your work? Post a short note about what you learned, or your favorite paragraph, in the course community or on your own page. Sharing is optional.\u003c/p\u003e"},{"t":"divider"}]},{"title":"","kind":"section","intro":"","passingScore":null,"blocks":[]},{"title":"Course summary","kind":"lesson","intro":"","passingScore":null,"blocks":[{"t":"statement","html":"\u003cp\u003eCongratulations! You have completed Write Your Way In.\u003c/p\u003e"},{"t":"text","level":2,"heading":"","html":"\u003cp\u003eYou planned and drafted with a process, learned how genres work, used sources with integrity, and turned feedback into better writing. Keep your Feedback Diary and your final essay. They show how far you have come.\u003c/p\u003e"}]}]};
